<?php
namespace App\Services\POS;
use App\Models\{Account,Folio,KitchenTicket,MenuItem,Payment,PosOrder,PosOrderItem,RestaurantTable,RoomServiceRequest,Stay}; use App\Services\Accounting\AccountingService; use App\Services\Folios\FolioService; use App\Services\Inventory\InventoryService; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use RuntimeException;
class PosService{
 public function __construct(private FolioService $folios,private InventoryService $inventory){}
 public function createOrder(array $data,int $propertyId,int $userId):PosOrder{return DB::transaction(function()use($data,$propertyId,$userId){$table=null;if(!empty($data['restaurant_table_id'])){$table=RestaurantTable::where('property_id',$propertyId)->findOrFail($data['restaurant_table_id']);if($table->status==='occupied')throw new RuntimeException('This table already has an active order.');}$stay=null;if(!empty($data['stay_id'])){$stay=Stay::with('guest')->where('property_id',$propertyId)->where('status','in_house')->findOrFail($data['stay_id']);}$order=PosOrder::create(['property_id'=>$propertyId,'outlet_id'=>$data['outlet_id'],'restaurant_table_id'=>$table?->id,'stay_id'=>$stay?->id,'guest_id'=>$stay?->guest_id,'opened_by'=>$userId,'order_number'=>'POS-'.now()->format('YmdHis').'-'.strtoupper(Str::random(4)),'service_type'=>$data['service_type']??'dine_in','status'=>'open','customer_name'=>$data['customer_name']??$stay?->guest?->full_name,'room_number'=>$stay?->room?->room_number,'notes'=>$data['notes']??null,'opened_at'=>now()]);if($table)$table->update(['status'=>'occupied']);if(($data['service_type']??null)==='room_service'&&$stay)RoomServiceRequest::create(['property_id'=>$propertyId,'stay_id'=>$stay->id,'guest_id'=>$stay->guest_id,'pos_order_id'=>$order->id,'type'=>'food','request'=>'Food and beverage order '.$order->order_number,'status'=>'new']);return $order;});}
 public function addItem(PosOrder $order,MenuItem $menu,float $quantity,array $modifierIds=[],?string $notes=null):PosOrderItem{return DB::transaction(function()use($order,$menu,$quantity,$modifierIds,$notes){if(in_array($order->status,['paid','cancelled'],true))throw new RuntimeException('This order is closed.');if($menu->property_id!==$order->property_id)throw new RuntimeException('Invalid menu item.');$modifiers=$menu->modifiers()->whereIn('menu_modifiers.id',$modifierIds)->get();$modifierUnit=(float)$modifiers->sum('price_delta');$base=(float)$menu->price*$quantity;$modifierTotal=$modifierUnit*$quantity;$tax=($base+$modifierTotal)*((float)$menu->tax_rate/100);$service=($base+$modifierTotal)*((float)$menu->service_charge_rate/100);$item=$order->items()->create(['menu_item_id'=>$menu->id,'item_name'=>$menu->name,'quantity'=>$quantity,'unit_price'=>$menu->price,'modifier_total'=>$modifierTotal,'tax_amount'=>$tax,'service_charge_amount'=>$service,'discount_amount'=>0,'line_total'=>$base+$modifierTotal+$tax+$service,'kitchen_status'=>$menu->send_to_kitchen?'new':'not_required','notes'=>$notes]);foreach($modifiers as $m)$item->modifiers()->create(['menu_modifier_id'=>$m->id,'name'=>$m->name,'price_delta'=>$m->price_delta]);$this->recalculate($order);return $item;});}
 public function sendToKitchen(PosOrder $order):KitchenTicket{return DB::transaction(function()use($order){$ticket=KitchenTicket::firstOrCreate(['pos_order_id'=>$order->id],['property_id'=>$order->property_id,'outlet_id'=>$order->outlet_id,'ticket_number'=>'KIT-'.now()->format('YmdHis').'-'.strtoupper(Str::random(4)),'status'=>'new']);$order->update(['status'=>'sent']);return $ticket;});}
 public function setItemKitchenStatus(PosOrderItem $item,string $status,int $userId):void{DB::transaction(function()use($item,$status,$userId){$item->update(['kitchen_status'=>$status]);if(in_array($status,['ready','served'],true))$this->inventory->consumeForOrderItem($item,$userId);$order=$item->order()->with('items')->first();$ticket=$order->kitchenTicket;if($ticket){$updates=['status'=>$status];if($status==='accepted')$updates+=['accepted_by'=>$userId,'accepted_at'=>now()];if($status==='ready')$updates['ready_at']=now();if($status==='served')$updates['served_at']=now();$ticket->update($updates);}if($status==='ready')$order->update(['status'=>'ready']);elseif($status==='served'&&$order->items()->whereNotIn('kitchen_status',['served','not_required','cancelled'])->doesntExist())$order->update(['status'=>'served']);});}
 public function settle(PosOrder $order,array $data,int $userId):PosOrder{return DB::transaction(function()use($order,$data,$userId){$order=$this->recalculate($order);$amount=(float)$data['amount'];$outstanding=(float)$order->grand_total-(float)$order->paid_total;if($amount<=0||$amount>$outstanding+0.009)throw new RuntimeException('Payment amount exceeds the outstanding order balance.');if(($data['method']??'')==='room_charge'){if(!$order->stay_id)throw new RuntimeException('Charge-to-room requires an active in-house stay.');$stay=Stay::with('reservation')->where('property_id',$order->property_id)->where('status','in_house')->findOrFail($order->stay_id);$folio=Folio::where('stay_id',$stay->id)->orWhere('reservation_id',$stay->reservation_id)->first();if(!$folio)$folio=$this->folios->ensureForReservation($stay->reservation,$stay);$this->folios->addCharge($folio,['department'=>$order->outlet?->type==='bar'?'bar':'restaurant','description'=>'POS '.$order->order_number.' - '.$order->outlet?->name,'quantity'=>1,'unit_price'=>$amount,'tax_amount'=>0],$userId);Payment::create(['property_id'=>$order->property_id,'guest_id'=>$order->guest_id,'reservation_id'=>$stay->reservation_id,'folio_id'=>$folio->id,'pos_order_id'=>$order->id,'reference'=>'ROOM-'.now()->format('YmdHis').'-'.Str::upper(Str::random(4)),'method'=>'room_charge','status'=>'successful','currency'=>config('hms.currency','UGX'),'amount'=>$amount,'description'=>'Transferred to room folio','paid_at'=>now(),'received_by'=>$userId]);}else{$payment=Payment::create(['property_id'=>$order->property_id,'guest_id'=>$order->guest_id,'pos_order_id'=>$order->id,'reference'=>'POSPAY-'.now()->format('YmdHis').'-'.Str::upper(Str::random(4)),'method'=>$data['method'],'gateway'=>$data['gateway']??null,'status'=>'successful','currency'=>config('hms.currency','UGX'),'amount'=>$amount,'payer_phone'=>$data['payer_phone']??null,'gateway_reference'=>$data['gateway_reference']??null,'description'=>'POS '.$order->order_number,'paid_at'=>now(),'received_by'=>$userId]);if(Account::where('property_id',$order->property_id)->where('code','1000')->exists()){$je=app(AccountingService::class)->postPosCashSale($order->property_id,$payment->id,$order->outlet?->type==='bar'?'bar':'restaurant',$payment->method,(float)$payment->amount,$userId);$payment->update(['journal_entry_id'=>$je->id]);} if($order->guest_id && config('hms.loyalty_spend_per_point',0)>0){$guest=\App\Models\Guest::find($order->guest_id);$points=(int) floor(((float)$payment->amount)/config('hms.loyalty_spend_per_point'));if($guest&&$points>0)app(\App\Services\CRM\LoyaltyService::class)->add($guest,$points,'Points earned from POS '.$order->order_number,$payment,$userId);}}foreach($order->items()->whereNull('stock_deducted_at')->get() as $item)$this->inventory->consumeForOrderItem($item,$userId);$order=$this->recalculate($order);$balance=(float)$order->grand_total-(float)$order->paid_total;$order->update(['status'=>$balance<=0.009?'paid':'partially_paid','closed_by'=>$balance<=0.009?$userId:null,'closed_at'=>$balance<=0.009?now():null]);if($balance<=0.009&&$order->table)$order->table->update(['status'=>'available']);return $order->fresh();});}
 public function recalculate(PosOrder $order):PosOrder{$subtotal=(float)$order->items()->selectRaw('COALESCE(SUM((quantity * unit_price) + modifier_total),0) AS total')->value('total');$tax=(float)$order->items()->sum('tax_amount');$service=(float)$order->items()->sum('service_charge_amount');$discount=(float)$order->items()->sum('discount_amount');$paid=(float)$order->payments()->where('status','successful')->sum('amount');$order->update(['subtotal'=>$subtotal,'tax_total'=>$tax,'service_charge_total'=>$service,'discount_total'=>$discount,'grand_total'=>$subtotal+$tax+$service-$discount,'paid_total'=>$paid]);return $order->fresh();}
}
